#!/usr/bin/env python3
"""Compare completed curved-cylinder outputs on identical VTK sample grids.

This is unweighted sample RMS, not a physical-space L2 norm. Existing MFEM VTK
and shock-QoI readers remain authoritative. Run only after GPU timing finishes.
Example from the repository:
  python3 /tmp/dg-igr-breakthrough/analyze_cylinder.py \
    --reference /tmp/dg-igr-breakthrough/cylinder-reference \
    --candidates /tmp/dg-igr-breakthrough/cylinder-cg \
                 /tmp/dg-igr-breakthrough/cylinder-patch4-fp32 \
    --output /tmp/dg-igr-breakthrough/cylinder-quality.json
"""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import math
from pathlib import Path
import struct
import sys


def module_at(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def command_options(command):
    options = {}
    for i, value in enumerate(command):
        if value.startswith('--'):
            options[value] = command[i+1] if i+1 < len(command) and not command[i+1].startswith('--') else True
    return options


def complete_record(path, target):
    manifest = path/'run.json'
    record = json.loads(manifest.read_text())
    if record.get('returncode') != 0 or record.get('timeout') or record.get('timed_out'):
        raise ValueError(f'{path}: run is not successfully completed; VTK will not be read')
    summaries = record.get('summaries', {})
    summary = summaries.get('[explicit-time]:run-summary', {}) if isinstance(summaries, dict) else {}
    if not summary:
        for line in summaries if isinstance(summaries, list) else []:
            if line.startswith('[explicit-time]') and 'event=run-summary' in line:
                summary = dict(token.split('=', 1) for token in line.split() if '=' in token)
    final_time = float(summary.get('final_time', 'nan'))
    if str(summary.get('success')) != '1' or not math.isfinite(final_time) or abs(final_time-target) > 1e-12:
        raise ValueError(f'{path}: no successful explicit-time summary at target {target}')
    return record, summary, sha(manifest)


INTEGER_TYPES = {'Int32': ('i', 4), 'UInt32': ('I', 4), 'Int64': ('q', 8),
                 'UInt64': ('Q', 8), 'UInt8': ('B', 1)}


def integers(qoi, root, node, count):
    kind = node.get('type')
    if kind not in INTEGER_TYPES:
        raise ValueError(f'Unsupported cell array type {kind}')
    code, size = INTEGER_TYPES[kind]
    if node.get('format', 'ascii') == 'ascii':
        values = [int(token) for token in (node.text or '').split()]
    elif node.get('format') == 'binary':
        payload = qoi._decode_binary(root, node, count*size, 'cell topology')
        byte_order = root.get('byte_order', 'LittleEndian')
        if byte_order not in ('LittleEndian', 'BigEndian'):
            raise ValueError('Unknown VTK byte order')
        endian = '<' if byte_order == 'LittleEndian' else '>'
        values = [x[0] for x in struct.iter_unpack(endian+code, payload)]
    else:
        raise ValueError('Unsupported cell array format')
    if len(values) != count:
        raise ValueError('Incorrect cell topology array length')
    return values


def geometry(qoi, compare, frame, vtk_root, limits, fields):
    digest = hashlib.sha256()
    point_schemas, piece_counts, hashes = [], [], []
    for path in compare.iter_piece_paths(frame.path):
        path.relative_to(vtk_root.resolve())
        root = qoi._read_xml(path, limits)
        pieces = list(qoi._descendants(root, 'Piece'))
        if len(pieces) != 1:
            raise ValueError('Require one Piece per VTU')
        piece = pieces[0]
        np, nc = int(piece.get('NumberOfPoints')), int(piece.get('NumberOfCells'))
        if np <= 0 or nc <= 0:
            raise ValueError('Empty geometry')
        cells = qoi._only_child(piece, 'Cells', str(path))
        cell_arrays = list(qoi._children(cells, 'DataArray'))
        arrays = {node.get('Name'): node for node in cell_arrays}
        if len(cell_arrays) != 3 or set(arrays) != {'connectivity', 'offsets', 'types'}:
            raise ValueError('Unexpected/missing VTK cell topology arrays')
        offsets = integers(qoi, root, arrays['offsets'], nc)
        if any(b <= a for a, b in zip([0]+offsets[:-1], offsets)) or offsets[-1] > 256*nc:
            raise ValueError('Invalid or excessive VTK cell offsets')
        connectivity = integers(qoi, root, arrays['connectivity'], offsets[-1])
        types = integers(qoi, root, arrays['types'], nc)
        if any(index < 0 or index >= np for index in connectivity):
            raise ValueError('Out-of-range VTK connectivity')
        for values in ([np, nc], offsets, connectivity, types):
            digest.update(struct.pack('<Q', len(values)))
            for value in values:
                digest.update(struct.pack('<q', value))
        point_data = qoi._only_child(piece, 'PointData', str(path))
        named = qoi._named_arrays(point_data, path)
        point_schemas.append({name: [node.get('type'), qoi._component_count(node, name)]
                              for name, node in named.items()})
        piece_counts.append({'points': np, 'cells': nc})
        hashes.append({'path': str(path), 'sha256': sha(path)})
    for point in fields.points:
        digest.update(struct.pack('<3d', *point))
    return {'geometry_sha256': digest.hexdigest(), 'piece_counts': piece_counts,
            'point_array_schemas': point_schemas, 'files': hashes}


def stats(compare, reference, candidate):
    if any(not math.isfinite(x) for x in reference) or any(not math.isfinite(x) for x in candidate):
        raise ValueError('Nonfinite comparison input')
    result = compare.diff_stats(reference, candidate)
    return {'sample_count': result['count'], 'rms_absolute': result['rms'],
            'relative_rms': result['rel_rms'] if math.isfinite(result['rel_rms']) else None,
            'relative_rms_defined': math.isfinite(result['rel_rms']),
            'max_absolute': result['max_abs'], 'mean_absolute': result['mean_abs']}


def samples(qoi, fields, gamma):
    pressure = qoi.reconstruct_pressure(fields, gamma)
    result = {'density': fields.density, 'energy': fields.energy, 'sigma': fields.sigma,
              'pressure_reconstructed': pressure}
    for component in range(len(fields.momentum[0])):
        result[f'momentum_{component}'] = [value[component] for value in fields.momentum]
    if min(pressure) <= 0:
        raise ValueError('Nonpositive pressure at saved VTK samples')
    minima = {'density': min(fields.density), 'pressure_reconstructed': min(pressure),
              'sigma': min(fields.sigma), 'sigma_maximum': max(fields.sigma)}
    return result, minima


def extract_profile(qoi, fields, args, half_width, bin_width):
    profile = qoi.make_profile(fields, y=args.center_y, x_min=args.profile_x_min,
        x_max=args.center_x-args.radius, half_width=half_width, bin_width=bin_width,
        coordinate_tolerance=1e-10, length_scale=args.radius)
    position, standoff, thickness = qoi.shock_metrics(profile, args.center_x-args.radius, args.radius)
    spacings = [b-a for a,b in zip(profile.x[:-1], profile.x[1:])]
    gradients = [abs(b-a)/dx for a,b,dx in zip(profile.density[:-1],profile.density[1:],spacings)]
    peak = max(range(len(gradients)), key=gradients.__getitem__)
    return profile, {'shock_position_proxy': position, 'standoff_proxy': standoff,
        'thickness_over_radius_proxy': thickness, 'profile_sample_count': len(profile.x),
        'peak_gradient_bracket': [profile.x[peak], profile.x[peak+1]],
        'maximum_sample_spacing': max(spacings), 'density_profile_range': max(profile.density)-min(profile.density),
        'half_width': half_width, 'bin_width': bin_width,
        'x': profile.x, 'density': profile.density}


def load(qoi, compare, path, args, limits):
    record, summary, manifest_sha = complete_record(path, args.target_time)
    vtk_root = path/'vtk'
    frame = qoi.select_frame(vtk_root, args.target_time, '', limits, 1e-12, 1e-12)
    fields = qoi.load_frame(frame, vtk_root.resolve(), limits)
    geometrical = geometry(qoi, compare, frame, vtk_root, limits, fields)
    data, minima = samples(qoi, fields, args.gamma)
    return {'record': record, 'summary': summary, 'frame': frame, 'fields': fields,
            'geometry': geometrical, 'samples': data, 'minima': minima, 'manifest_sha': manifest_sha}


SPATIAL_OPTIONS = ('--regularization', '--discretization', '--dg-backend', '--order',
    '--serial-refine', '--parallel-refine', '--c-alpha', '--igr-alpha-length',
    '--dgsem-stab', '--dgsem-volume-flux', '--dgsem-volume-dissipation',
    '--dgsem-surface-flux', '--igr-space', '--igr-grad', '--igr-ip-kind',
    '--igr-exact-dg-face', '--igr-sigma-cadence', '--positivity-limiter',
    '--no-igr-sigma-cfl', '--no-igr-sigma-rusanov', '--no-igr-invariant-domain-flux')


def equivalent(a, b):
    if a == b:
        return True
    try:
        return float(a) == float(b)
    except (TypeError, ValueError):
        return False


def identity(record):
    return {key: record.get(key) for key in ('source_head','source_status','head','status',
        'executable_sha256','app_sha256','mesh_sha256','command','environment','wall_seconds') if key in record}


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo', type=Path, default=Path.cwd())
    p.add_argument('--reference', type=Path, required=True)
    p.add_argument('--candidates', type=Path, nargs='+', required=True)
    p.add_argument('--output', type=Path, required=True)
    p.add_argument('--target-time', type=float, default=.5)
    p.add_argument('--gamma', type=float, default=1.4)
    p.add_argument('--center-x', type=float, default=.6)
    p.add_argument('--center-y', type=float, default=0)
    p.add_argument('--radius', type=float, default=.25)
    p.add_argument('--profile-x-min', type=float, default=None)
    p.add_argument('--profile-half-width', type=float, default=.005)
    p.add_argument('--profile-bin-width', type=float, default=.005)
    args = p.parse_args()
    numbers = [args.target_time,args.gamma,args.center_x,args.center_y,args.radius,args.profile_half_width,args.profile_bin_width]
    if any(not math.isfinite(x) for x in numbers) or min(args.target_time,args.radius,args.profile_half_width,args.profile_bin_width) <= 0 or args.gamma <= 1:
        p.error('Invalid finite/positive physical or profile parameters')
    if args.profile_x_min is not None and (not math.isfinite(args.profile_x_min) or args.profile_x_min >= args.center_x-args.radius):
        p.error('Invalid profile lower endpoint')
    qoi_path = args.repo/'scripts/perf/shock_qoi.py'
    compare_path = args.repo/'tests/scripts/compare_vtk_pvd_fields.py'
    qoi = module_at('cylinder_shock_qoi', qoi_path)
    compare = module_at('cylinder_vtk_compare', compare_path)
    limits = qoi.Limits(128*1024**2, 2_000_000, 64, 16)
    reference = load(qoi, compare, args.reference, args, limits)
    reference_options = command_options(reference['record']['command'])
    profile_configs = [(args.profile_half_width,args.profile_bin_width),
                       (2*args.profile_half_width,args.profile_bin_width),
                       (args.profile_half_width,args.profile_bin_width/2)]
    reference_profiles = []
    for half, bin_width in profile_configs:
        try:
            profile, values = extract_profile(qoi, reference['fields'], args, half, bin_width)
            reference_profiles.append((profile,values,None))
        except qoi.ShockQOIError as error:
            reference_profiles.append((None,None,str(error)))
    rows = []
    for path in args.candidates:
        try:
            candidate = load(qoi, compare, path, args, limits)
            candidate_options = command_options(candidate['record']['command'])
            mismatches = {key:[reference_options.get(key),candidate_options.get(key)] for key in SPATIAL_OPTIONS
                          if not equivalent(reference_options.get(key),candidate_options.get(key))}
            if mismatches or candidate['record'].get('mesh_sha256') != reference['record'].get('mesh_sha256'):
                raise ValueError(f'Spatial/physical or mesh identity mismatch: {mismatches}')
            for key in ('geometry_sha256','piece_counts','point_array_schemas'):
                if candidate['geometry'][key] != reference['geometry'][key]:
                    raise ValueError(f'Same-grid requirement failed: {key}')
            if candidate['fields'].points != reference['fields'].points:
                raise ValueError('Decoded point coordinates/order differ')
            if set(candidate['samples']) != set(reference['samples']):
                raise ValueError('Required physical sample arrays differ')
            field_errors = {name:stats(compare,ref,candidate['samples'][name]) for name,ref in reference['samples'].items()}
            profiles = []
            for (half,bin_width),(ref_profile,ref_qoi,ref_error) in zip(profile_configs,reference_profiles):
                if ref_error:
                    profiles.append({'available':False,'reason':ref_error,'half_width':half,'bin_width':bin_width})
                    continue
                try:
                    profile, proxy = extract_profile(qoi,candidate['fields'],args,half,bin_width)
                    if profile.x != ref_profile.x:
                        raise ValueError('Binned profile coordinates differ despite matched geometry')
                    l1,l2 = qoi.profile_errors(profile,ref_profile,minimum_overlap_fraction=1.0)
                    profiles.append({'available':True,'reference':ref_qoi,'candidate':proxy,
                        'density_piecewise_linear_mean_absolute_error':l1,
                        'density_piecewise_linear_rms_error':l2,
                        'standoff_proxy_difference':None if proxy['standoff_proxy'] is None or ref_qoi['standoff_proxy'] is None else proxy['standoff_proxy']-ref_qoi['standoff_proxy']})
                except (qoi.ShockQOIError,ValueError) as error:
                    profiles.append({'available':False,'reason':str(error),'half_width':half,'bin_width':bin_width})
            rows.append({'candidate':str(path.resolve()),'valid_same_grid_comparison':True,
                'identity':identity(candidate['record']),'run_manifest_sha256':candidate['manifest_sha'],
                'time_summary':candidate['summary'],'geometry':candidate['geometry'],
                'positive_saved_samples':True,'sample_minima':candidate['minima'],
                'unweighted_sample_errors':field_errors,'profile_proxies':profiles,
                'conservation_and_boundary_balance':'Not inferable from VTK point samples; use recorded application balance telemetry.'})
        except (ValueError,OSError,KeyError,qoi.ShockQOIError) as error:
            rows.append({'candidate':str(path.resolve()),'valid_same_grid_comparison':False,'error':str(error)})
    result = {'schema':'curved-cylinder-same-grid-quality-v1','postprocessor_sha256':sha(__file__),
        'existing_reader_sha256':{'shock_qoi':sha(qoi_path),'compare_vtk_pvd_fields':sha(compare_path)},
        'reference':{'path':str(args.reference.resolve()),'identity':identity(reference['record']),
            'run_manifest_sha256':reference['manifest_sha'],'time_summary':reference['summary'],
            'geometry':reference['geometry'],'positive_saved_samples':True,'sample_minima':reference['minima']},
        'target_time':args.target_time,'gamma':args.gamma,
        'interpretation':'Unweighted RMS over the identical ordered VTK sample grid, including duplicated DG-face points. These are NOT volume-weighted physical L2 errors or independent spatial/time reference validation. Pressure is reconstructed from conserved fields in FP64; positivity holds only at saved samples.',
        'profile_interpretation':'Near-centerline density is binned in x using the existing shock_qoi reader. Shock/standoff select the largest discrete density gradient; thickness is density range divided by that gradient and cylinder radius. These are sampling-dependent proxies, not shock-fitting or resolved physical widths. Two strip/bin ablations expose extraction sensitivity.',
        'results':rows}
    args.output.parent.mkdir(parents=True,exist_ok=True)
    temporary = args.output.with_suffix(args.output.suffix+'.tmp')
    temporary.write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    temporary.replace(args.output)
    print(json.dumps({'output':str(args.output.resolve()),'valid':sum(row['valid_same_grid_comparison'] for row in rows),'total':len(rows)}))
    return 0 if all(row['valid_same_grid_comparison'] for row in rows) else 2


if __name__ == '__main__':
    raise SystemExit(main())

