    '--serial-refine', '--parallel-refine', '--c-alpha', '--igr-alpha-length',
    '--dgsem-stab', '--dgsem-volume-flux', '--dgsem-volume-dissipation',
    '--dgsem-surface-flux', '--igr-space', '--igr-grad', '--igr-ip-kind',
    '--igr-exact-dg-face', '--igr-sigma-cadence', '--positivity-limiter',
    '--no-igr-sigma-cfl', '--no-igr-sigma-rusanov', '--no-igr-invariant-domain-flux')


def equivalent(a, b):
    if a == b:
        return True
    try:
        return float(a) == float(b)
    except (TypeError, ValueError):
        return False


def identity(record):
    return {key: record.get(key) for key in ('source_head','source_status','head','status',
        'executable_sha256','app_sha256','mesh_sha256','command','environment','wall_seconds') if key in record}


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo', type=Path, default=Path.cwd())
    p.add_argument('--reference', type=Path, required=True)
    p.add_argument('--candidates', type=Path, nargs='+', required=True)
    p.add_argument('--output', type=Path, required=True)
    p.add_argument('--target-time', type=float, default=.5)
    p.add_argument('--gamma', type=float, default=1.4)
    p.add_argument('--center-x', type=float, default=.6)
    p.add_argument('--center-y', type=float, default=0)
    p.add_argument('--radius', type=float, default=.25)
    p.add_argument('--profile-x-min', type=float, default=None)
    p.add_argument('--profile-half-width', type=float, default=.005)
    p.add_argument('--profile-bin-width', type=float, default=.005)
    args = p.parse_args()
    numbers = [args.target_time,args.gamma,args.center_x,args.center_y,args.radius,args.profile_half_width,args.profile_bin_width]
    if any(not math.isfinite(x) for x in numbers) or min(args.target_time,args.radius,args.profile_half_width,args.profile_bin_width) <= 0 or args.gamma <= 1:
        p.error('Invalid finite/positive physical or profile parameters')
    if args.profile_x_min is not None and (not math.isfinite(args.profile_x_min) or args.profile_x_min >= args.center_x-args.radius):
        p.error('Invalid profile lower endpoint')
    qoi_path = args.repo/'scripts/perf/shock_qoi.py'
    compare_path = args.repo/'tests/scripts/compare_vtk_pvd_fields.py'
    qoi = module_at('cylinder_shock_qoi', qoi_path)
    compare = module_at('cylinder_vtk_compare', compare_path)
    limits = qoi.Limits(128*1024**2, 2_000_000, 64, 16)
    reference = load(qoi, compare, args.reference, args, limits)
    reference_options = command_options(reference['record']['command'])
    profile_configs = [(args.profile_half_width,args.profile_bin_width),
                       (2*args.profile_half_width,args.profile_bin_width),
                       (args.profile_half_width,args.profile_bin_width/2)]
    reference_profiles = []
    for half, bin_width in profile_configs:
        try:
            profile, values = extract_profile(qoi, reference['fields'], args, half, bin_width)
            reference_profiles.append((profile,values,None))
        except qoi.ShockQOIError as error:
            reference_profiles.append((None,None,str(error)))
    rows = []
    for path in args.candidates:
        try:
            candidate = load(qoi, compare, path, args, limits)
            candidate_options = command_options(candidate['record']['command'])
            mismatches = {key:[reference_options.get(key),candidate_options.get(key)] for key in SPATIAL_OPTIONS
                          if not equivalent(reference_options.get(key),candidate_options.get(key))}
            if mismatches or candidate['record'].get('mesh_sha256') != reference['record'].get('mesh_sha256'):
                raise ValueError(f'Spatial/physical or mesh identity mismatch: {mismatches}')
            for key in ('geometry_sha256','piece_counts','point_array_schemas'):
                if candidate['geometry'][key] != reference['geometry'][key]:
                    raise ValueError(f'Same-grid requirement failed: {key}')
            if candidate['fields'].points != reference['fields'].points:
                raise ValueError('Decoded point coordinates/order differ')
            if set(candidate['samples']) != set(reference['samples']):
                raise ValueError('Required physical sample arrays differ')
            field_errors = {name:stats(compare,ref,candidate['samples'][name]) for name,ref in reference['samples'].items()}
            profiles = []
            for (half,bin_width),(ref_profile,ref_qoi,ref_error) in zip(profile_configs,reference_profiles):
                if ref_error:
                    profiles.append({'available':False,'reason':ref_error,'half_width':half,'bin_width':bin_width})
                    continue
                try:
                    profile, proxy = extract_profile(qoi,candidate['fields'],args,half,bin_width)
                    if profile.x != ref_profile.x:
                        raise ValueError('Binned profile coordinates differ despite matched geometry')
                    l1,l2 = qoi.profile_errors(profile,ref_profile,minimum_overlap_fraction=1.0)
                    profiles.append({'available':True,'reference':ref_qoi,'candidate':proxy,
                        'density_piecewise_linear_mean_absolute_error':l1,
                        'density_piecewise_linear_rms_error':l2,
                        'standoff_proxy_difference':None if proxy['standoff_proxy'] is None or ref_qoi['standoff_proxy'] is None else proxy['standoff_proxy']-ref_qoi['standoff_proxy']})
                except (qoi.ShockQOIError,ValueError) as error:
                    profiles.append({'available':False,'reason':str(error),'half_width':half,'bin_width':bin_width})
            rows.append({'candidate':str(path.resolve()),'valid_same_grid_comparison':True,
                'identity':identity(candidate['record']),'run_manifest_sha256':candidate['manifest_sha'],
                'time_summary':candidate['summary'],'geometry':candidate['geometry'],
                'positive_saved_samples':True,'sample_minima':candidate['minima'],
                'unweighted_sample_errors':field_errors,'profile_proxies':profiles,
                'conservation_and_boundary_balance':'Not inferable from VTK point samples; use recorded application balance telemetry.'})
        except (ValueError,OSError,KeyError,qoi.ShockQOIError) as error:
            rows.append({'candidate':str(path.resolve()),'valid_same_grid_comparison':False,'error':str(error)})
    result = {'schema':'curved-cylinder-same-grid-quality-v1','postprocessor_sha256':sha(__file__),
        'existing_reader_sha256':{'shock_qoi':sha(qoi_path),'compare_vtk_pvd_fields':sha(compare_path)},
        'reference':{'path':str(args.reference.resolve()),'identity':identity(reference['record']),
            'run_manifest_sha256':reference['manifest_sha'],'time_summary':reference['summary'],
            'geometry':reference['geometry'],'positive_saved_samples':True,'sample_minima':reference['minima']},
        'target_time':args.target_time,'gamma':args.gamma,
        'interpretation':'Unweighted RMS over the identical ordered VTK sample grid, including duplicated DG-face points. These are NOT volume-weighted physical L2 errors or independent spatial/time reference validation. Pressure is reconstructed from conserved fields in FP64; positivity holds only at saved samples.',
        'profile_interpretation':'Near-centerline density is binned in x using the existing shock_qoi reader. Shock/standoff select the largest discrete density gradient; thickness is density range divided by that gradient and cylinder radius. These are sampling-dependent proxies, not shock-fitting or resolved physical widths. Two strip/bin ablations expose extraction sensitivity.',
        'results':rows}
    args.output.parent.mkdir(parents=True,exist_ok=True)
    temporary = args.output.with_suffix(args.output.suffix+'.tmp')
    temporary.write_text(json.dumps(result,indent=2,allow_nan=False)+'\n')
    temporary.replace(args.output)
    print(json.dumps({'output':str(args.output.resolve()),'valid':sum(row['valid_same_grid_comparison'] for row in rows),'total':len(rows)}))
    return 0 if all(row['valid_same_grid_comparison'] for row in rows) else 2


if __name__ == '__main__':
    raise SystemExit(main())

